@if($manager)<section class="card"><h2>Proponer un calendario</h2><p class="help">El planificador elige tutores vinculados al hospital, prioriza la menor carga acumulada y deja pendientes los turnos sin cobertura. Una guardia admite un tutor y un interno. El descanso es un parámetro que debe validar Coordinación.</p><form method="post" action="{{ route('shifts.generate') }}">@csrf<div class="form-grid"><label>Nombre del calendario<input name="name" required maxlength="150" placeholder="Guardias · primera semana"></label><label>Descanso mínimo entre turnos (horas)<input type="number" name="rest_hours" min="0" max="48" value="12" required></label></div><div id="shift-rows"><div class="form-grid shift-row" style="margin-top:20px"><label>Rote<select name="slots[0][assignment_id]" required><option value="">Selecciona un interno y rote</option>@foreach($assignments as $a)<option value="{{ $a->id }}">#{{ $a->id }} · {{ $a->intern }} · {{ $a->hospital }}</option>@endforeach</select></label><label>Inicio<input type="datetime-local" name="slots[0][starts_at]" required></label><label>Fin<input type="datetime-local" name="slots[0][ends_at]" required></label><button type="button" class="button subtle remove-shift">Quitar turno</button></div></div><div class="form-actions"><button type="button" id="add-shift" class="button secondary">+ Añadir turno</button><button>Generar propuesta</button></div></form></section>
<section class="card"><h2>Calendarios para revisión</h2><div class="table-wrap"><table><thead><tr><th>Calendario</th><th>Descanso</th><th>Estado</th><th>Acción</th></tr></thead><tbody>@forelse($batches as $b)<tr><td>{{ $b->name }}</td><td>{{ $b->rest_hours }} h</td><td><span data-run-status="{{ route('shifts.status',$b->id) }}" data-initial="{{ $b->execution_status }}">{{ $b->execution_status }} · {{ $b->status }}</span>@if($b->diagnostic)<details><summary>Diagnóstico del cálculo</summary><pre class="wrap">{{ json_encode(json_decode($b->diagnostic,true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE) }}</pre></details>@endif</td><td>@if($b->status==='propuesta' && $b->execution_status==='completada')<form method="post" action="{{ route('shifts.approve',$b->id) }}" data-confirm="¿Aprobar este calendario? Se verificarán los cruces y descansos nuevamente.">@csrf<button class="button small">Aprobar</button></form>@elseif($b->status==='aprobada') Publicado @else Revisa el estado del cálculo @endif</td></tr>@empty<tr><td colspan="4">No hay calendarios propuestos.</td></tr>@endforelse</tbody></table></div></section>@endif
<section class="card"><h2 id="calendario">Turnos {{ $manager?'propuestos y aprobados':'aprobados' }}</h2><div class="table-wrap"><table><thead><tr><th>Calendario</th><th>Interno</th><th>Tutor</th><th>Inicio</th><th>Fin</th><th>Estado</th><th>Cumplimiento</th></tr></thead><tbody>@forelse($shifts as $s)<tr><td>{{ $s->batch }}</td><td>{{ $s->intern }}</td><td class="wrap">{{ $s->tutor ?? $s->reason }}</td><td>{{ $s->starts_at }}</td><td>{{ $s->ends_at }}</td><td><span class="badge {{ $s->status==='propuesta'?'pending':'' }}">{{ $s->status }}</span></td><td>@if($s->performed)Registrado @elseif($s->status==='aprobada' && auth()->user()->role!=='interno')<a href="{{ route('clinical') }}#guardias">Registrar en seguimiento</a>@else Pendiente @endif</td></tr>@empty<tr><td colspan="7" class="empty">No hay turnos para mostrar.</td></tr>@endforelse</tbody></table></div></section>
@if($manager)<section class="card"><h2>Carga publicada por tutor</h2><div class="table-wrap"><table><thead><tr><th>Tutor</th><th>Turnos</th><th>Horas programadas</th></tr></thead><tbody>@foreach($shifts->where('status','aprobada')->groupBy('tutor') as $name=>$group)<tr><td>{{ $name }}</td><td>{{ $group->count() }}</td><td>{{ number_format($group->sum(fn($s)=>\Carbon\Carbon::parse($s->starts_at)->diffInMinutes(\Carbon\Carbon::parse($s->ends_at)))/60,1) }}</td></tr>@endforeach</tbody></table></div></section>@endif</x-layout>
